from math import comb
def expected_unique(counts, k):
    n = int(counts.sum())
    return sum(1 - (comb(n-int(c), k) / comb(n, k) if k <= n-int(c) else 0) for c in counts)
sample_n = int(df.groupby('recurrence_type').size().min())
pd.DataFrame({(kind, field): [expected_unique(group[field].value_counts(), sample_n)] for kind, group in df.groupby('recurrence_type') for field in ['destination_zone','purpose_group']})
